const renderers = {home,expertise,approach,insights,about,contact};
const titles = {home:'Shaping What Comes Next',expertise:'Expertise',approach:'Our Approach',insights:'Insights',about:'About',contact:'Contact'};
const parseRoute = () => {let file=location.pathname.split('/').pop() || 'index.html';let name=file==='index.html'?'home':file.replace(/\.html$/,'');return {page:pages.includes(name)?name:'home',query:new URLSearchParams(location.search)};};
// On mobile the drawer must be a viewport overlay, not an absolutely positioned child of a sticky header.
// Moving it out of the header also prevents iOS from attaching it to the header's original document position.
document.body.appendChild(mobileMenu);
const updateMobileMenuPosition = () => {
  const header=document.getElementById('header');
  const bottom=header.getBoundingClientRect().bottom;
  mobileMenu.style.setProperty('--kova-menu-top', `${Math.max(0, Math.min(window.innerHeight, bottom))}px`);
};
const closeMenu = () => {mobileMenu.hidden=true;menuBtn.setAttribute('aria-expanded','false');menuBtn.setAttribute('aria-label','Open navigation');document.body.classList.remove('menu-open');};
const updateNav = page => {document.querySelectorAll('a[data-route]').forEach(el=>{let act=el.dataset.route===page;el.classList.toggle('is-current',act);if(act)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')}); document.getElementById('utility-current').textContent=`${String(pages.indexOf(page)+1).padStart(2,'0')} / 06 — ${titles[page].toUpperCase()}`; document.getElementById('header-page-name').textContent=titles[page].toUpperCase(); document.title=`${titles[page]} — KOVA Planning Co.`;};
function mount(page,query){ROOT.innerHTML=renderers[page]()+gateway(page);ROOT.setAttribute('data-page',page);currentPage=page;updateNav(page);document.documentElement.style.scrollBehavior='auto';window.scrollTo(0,0);document.documentElement.scrollTop=0;document.body.scrollTop=0;requestAnimationFrame(()=>{document.documentElement.style.scrollBehavior=''}); closeMenu(); setupReveals(); if(page==='expertise') {const key=query.get('focus'); if(key&&topicContent[key]) selectTopic(key,true);const view=query.get('view');if(view==='anatomy'||view==='documents'||view==='coordination')requestAnimationFrame(()=>{document.getElementById(view==='anatomy'?'anatomy-of-consent':view==='documents'?'sample-documents':'project-coordination')?.scrollIntoView({behavior:'instant',block:'start'})})} if(page==='insights') {const key=query.get('guide')||query.get('article');if(key&&guides[key]) showGuide(key,false)} if(page==='contact')setupForm(); updateProgress();}
function go(){const {page,query}=parseRoute(); if(page===currentPage){if(page==='expertise'&&query.has('focus'))selectTopic(query.get('focus'),true);if(page==='expertise'&&query.has('view'))document.getElementById(query.get('view')==='anatomy'?'anatomy-of-consent':query.get('view')==='coordination'?'project-coordination':'sample-documents')?.scrollIntoView({behavior:reduceMotion?'instant':'smooth',block:'start'});if(page==='insights'&&(query.has('guide')||query.has('article')))showGuide(query.get('guide')||query.get('article'),true);else if(page==='insights'&&guideOpen)backToGuides();else if(!query.toString())window.scrollTo({top:0,behavior:reduceMotion?'auto':'smooth'});return;}if(busy)return;busy=true;closeMenu();if(reduceMotion){mount(page,query);busy=false;return;}transition.classList.remove('leaving');transition.classList.add('entering');window.setTimeout(()=>{mount(page,query);transition.classList.remove('entering');transition.classList.add('leaving')},430);window.setTimeout(()=>{transition.classList.remove('leaving');busy=false;},1090)}
function setupReveals(){if(reduceMotion)return;let targets=ROOT.querySelectorAll('.section-intro,.manifesto-grid,.topic-hero,.three-steps,.large-quote,.legal-grid,.principles-grid,.insights-grid,.anatomy-intro,.anatomy-board,.document-header,.sample-grid,.scenario-header,.home-intelligence-inner');targets.forEach(x=>x.classList.add('reveal'));let io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');io.unobserve(e.target)}}),{threshold:.09,rootMargin:'0px 0px -40px 0px'});targets.forEach(x=>io.observe(x));}
function selectTopic(key,scroll){if(!topicContent[key])return;let viewport=document.getElementById('topic-viewport');if(!viewport)return;viewport.classList.add('content-changing');window.setTimeout(()=>{viewport.innerHTML=topicPanel(key);viewport.classList.remove('content-changing');if(scroll){document.querySelector('.knowledge-section')?.scrollIntoView({behavior:reduceMotion?'auto':'smooth'})}},reduceMotion?0:150);document.querySelectorAll('.topic-tab').forEach(b=>{let on=b.dataset.topic===key;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on))});}
function selectStage(idx){let viewport=document.getElementById('stage-viewport');if(!viewport)return;viewport.classList.add('content-changing');window.setTimeout(()=>{viewport.innerHTML=stagePanel(idx);viewport.classList.remove('content-changing')},reduceMotion?0:140);document.querySelectorAll('.stage-tab').forEach(b=>{let on=+b.dataset.stage===idx;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on))});}
function showGuide(key,scroll){if(!guides[key])return;let vp=document.getElementById('insights-viewport');if(!vp)return;guideOpen=key;vp.innerHTML=guideMarkup(key);if(scroll)document.querySelector('.insights-content')?.scrollIntoView({behavior:reduceMotion?'auto':'smooth'});}
function backToGuides(){guideOpen=null;const vp=document.getElementById('insights-viewport');if(vp)vp.innerHTML=insightListing();history.replaceState(null,'','insights.html');document.querySelector('.insights-content')?.scrollIntoView({behavior:reduceMotion?'auto':'smooth'});}
function safe(s){return String(s||'').trim();}

// KOVA SELECT / reusable, branded dropdown for all present and future select elements.
// Enhances standard <select> elements, retaining their real value for FormData.
function enhanceKovaSelects(root){
  root.querySelectorAll('select:not([data-kova-native])').forEach((native,index)=>{
    if(native.dataset.kovaEnhanced) return;
    native.dataset.kovaEnhanced='true';
    const originalRequired=native.required;
    native.required=false; // selection is validated against the branded control before creating the enquiry.
    native.classList.add('kova-select-native');
    native.tabIndex=-1;
    native.setAttribute('aria-hidden','true');
    const wrap=document.createElement('div');
    wrap.className='kova-select';
    native.parentNode.insertBefore(wrap,native);
    wrap.appendChild(native);
    const id=native.id||`kova-select-${index}`;
    native.id=id;
    const fieldLabel=native.closest('.kova-field')?.querySelector('.kova-field-label');
    const button=document.createElement('button');
    button.type='button';
    button.className='kova-select-trigger';
    button.id=`${id}-trigger`;
    button.setAttribute('role','combobox');
    button.setAttribute('aria-haspopup','listbox');
    button.setAttribute('aria-expanded','false');
    button.setAttribute('aria-controls',`${id}-options`);
    button.setAttribute('aria-required',String(originalRequired));
    if(fieldLabel?.id) button.setAttribute('aria-labelledby',`${fieldLabel.id} ${id}-value`);
    const value=document.createElement('span');value.className='kova-select-value is-placeholder';value.id=`${id}-value`;
    const chevron=document.createElement('span');chevron.className='kova-select-chevron';chevron.setAttribute('aria-hidden','true');
    button.append(value,chevron);
    const menu=document.createElement('div');
    menu.className='kova-select-menu';menu.id=`${id}-options`;
    menu.setAttribute('role','listbox');menu.setAttribute('aria-hidden','true');
    if(fieldLabel?.id) menu.setAttribute('aria-labelledby',fieldLabel.id);
    menu.tabIndex=-1;
    const choices=Array.from(native.options).filter(option=>option.value!==''&&!option.disabled);
    const items=choices.map((opt,i)=>{
      const item=document.createElement('button');
      item.type='button';item.setAttribute('role','option');item.tabIndex=-1;
      item.id=`${id}-option-${i}`;item.dataset.value=opt.value;
      item.className='kova-select-option';
      const n=document.createElement('span');n.className='kova-select-number';n.textContent=String(i+1).padStart(2,'0');
      const t=document.createElement('span');t.className='kova-select-option-text';t.textContent=opt.text;
      const mark=document.createElement('span');mark.className='kova-select-check';mark.setAttribute('aria-hidden','true');mark.innerHTML='<svg class="kova-line-arrow" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" aria-hidden="true" focusable="false"><path d="M7 25L25 7M10 7h15v15"/></svg>';
      item.append(n,t,mark); menu.appendChild(item);
      item.addEventListener('click',()=>choose(i));
      item.addEventListener('mousemove',()=>{active=i;markActive()});
      return item;
    });
    const error=document.createElement('p');error.className='kova-select-error';error.id=`${id}-error`;error.hidden=true;error.textContent='Please select a service to continue.';
    wrap.append(button,menu,error);
    let open=false,active=0;
    function markActive(){items.forEach((el,i)=>el.classList.toggle('is-highlighted',open&&i===active));if(open&&active>=0)button.setAttribute('aria-activedescendant',items[active].id);else button.removeAttribute('aria-activedescendant')}
    function sync(){
      const selected=native.options[native.selectedIndex];
      value.textContent=native.value?selected?.text:'Select a service';
      value.classList.toggle('is-placeholder',!native.value);
      wrap.classList.toggle('has-value',!!native.value);
      items.forEach(el=>{const selected=el.dataset.value===native.value;el.classList.toggle('is-selected',selected);el.setAttribute('aria-selected',String(selected))});
    }
    function setInvalid(invalid){wrap.classList.toggle('is-invalid',invalid);error.hidden=!invalid;button.setAttribute('aria-invalid',String(invalid));if(invalid)button.setAttribute('aria-describedby',error.id);else button.removeAttribute('aria-describedby')}
    function show(focus=false){
      if(open)return;
      // Only one KOVA dropdown is open at a time.
      document.querySelectorAll('.kova-select.is-open').forEach(other=>other!==wrap&&other.dispatchEvent(new Event('kova-close')));
      open=true;
      const spaceBelow=innerHeight-button.getBoundingClientRect().bottom;
      wrap.classList.toggle('opens-up',spaceBelow<Math.min(345,choices.length*49+24)&&button.getBoundingClientRect().top>spaceBelow);
      wrap.classList.add('is-open');
      button.setAttribute('aria-expanded','true');menu.setAttribute('aria-hidden','false');
      active=items.findIndex(i=>i.dataset.value===native.value);
      markActive();
    }
    function hide(restore=false){
      if(!open)return;
      open=false;wrap.classList.remove('is-open');
      button.setAttribute('aria-expanded','false');menu.setAttribute('aria-hidden','true');
      markActive();if(restore)button.focus({preventScroll:true});
    }
    function choose(i){if(!choices[i])return; native.value=choices[i].value;native.dispatchEvent(new Event('change',{bubbles:true}));setInvalid(false);sync();hide(true)}
    button.addEventListener('click',()=>open?hide():show(false));
    button.addEventListener('keydown',ev=>{
      // Keep DOM focus on the combobox; tell assistive tech which option is active.
      if(open&&(ev.key==='Enter'||ev.key===' ')){ev.preventDefault();choose(Math.max(0,active));return}
      if(['ArrowDown','ArrowUp','Home','End',' '].includes(ev.key)){
        ev.preventDefault();if(!open)show(false);
        if(ev.key==='End')active=items.length-1;
        else if(ev.key==='Home')active=0;
        else if(ev.key==='ArrowUp')active=active<=0?items.length-1:active-1;
        else if(ev.key==='ArrowDown')active=Math.min(items.length-1,active+1);
        markActive();items[active]?.scrollIntoView({block:'nearest'});
      }else if(ev.key==='Escape'&&open){ev.preventDefault();hide(true)}
    });
    menu.addEventListener('keydown',ev=>{
      if(ev.key==='Escape'){ev.preventDefault();hide(true);return}
      if(ev.key==='Tab'){hide();return}
      if(['ArrowDown','ArrowUp','Home','End','Enter',' '].includes(ev.key)){
        ev.preventDefault();
        if(ev.key==='Enter'||ev.key===' '){choose(active);return}
        if(ev.key==='End')active=items.length-1;
        else if(ev.key==='Home')active=0;
        else active=(active+(ev.key==='ArrowDown'?1:-1)+items.length)%items.length;
        markActive();items[active]?.focus({preventScroll:true});items[active]?.scrollIntoView({block:'nearest'});
      }
    });
    wrap.addEventListener('kova-close',()=>hide());
    document.addEventListener('pointerdown',ev=>{if(open&&!wrap.contains(ev.target))hide()});
    wrap.addEventListener('focusout',()=>setTimeout(()=>{if(open&&!wrap.contains(document.activeElement))hide()},0));
    native.addEventListener('change',sync);
    sync();
    wrap.kovaValidate=()=>{
      if(!originalRequired||native.value)return true;
      setInvalid(true);button.focus({preventScroll:false});show(false);return false;
    };
  });
}

function setupForm(){const form=document.getElementById('enquiry-form');if(!form)return;enhanceKovaSelects(form);form.addEventListener('submit',ev=>{ev.preventDefault();if(!form.querySelector('.kova-select')?.kovaValidate())return;if(!form.reportValidity())return;const d=new FormData(form);const summary=['KOVA PLANNING CO. — PROJECT ENQUIRY DRAFT','',`Name: ${safe(d.get('name'))}`,`Email: ${safe(d.get('email'))}`,`Phone: ${safe(d.get('phone'))||'Not provided'}`,`Site: ${safe(d.get('location'))||'Not provided'}`,`Service: ${safe(d.get('service'))}`,'', 'Project details:',safe(d.get('message')),'','IMPORTANT: This draft has NOT been sent.','This prototype does not send or store your information.'].join('\n'); const dialog=document.getElementById('enquiry-dialog');const body=document.getElementById('enquiry-dialog-body');body.innerHTML=`<div class="dialog-kicker">KOVA / ENQUIRY PREVIEW</div><h2>READY TO<br><em>TAKE THE NEXT STEP.</em></h2><p>We've prepared your project enquiry below. Nothing has been sent or saved online.</p><pre id="draft-text"></pre><div class="dialog-actions"><button type="button" class="btn btn-dark" id="copy-draft">Copy enquiry <span><svg class="kova-line-arrow" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" aria-hidden="true" focusable="false"><path d="M7 25L25 7M10 7h15v15"/></svg></span></button><button type="button" class="btn btn-outline" id="download-draft">Download .txt <span>↓</span></button></div><p id="draft-status" role="status">To send this in future, the live website will need a connected email or enquiry service.</p>`;body.querySelector('#draft-text').textContent=summary;dialog.showModal();body.querySelector('#copy-draft').addEventListener('click',()=>{navigator.clipboard?.writeText(summary).then(()=>{body.querySelector('#draft-status').textContent='Copied. This draft has not been sent.'}).catch(()=>{body.querySelector('#draft-status').textContent='Copy is unavailable in this browser. You can select the enquiry text manually.'})});body.querySelector('#download-draft').addEventListener('click',()=>{let blob=new Blob([summary],{type:'text/plain;charset=utf-8'});let url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download='KOVA_Enquiry_Draft.txt';a.click();window.setTimeout(()=>URL.revokeObjectURL(url),5000)});});}
function updateProgress(){let height=document.documentElement.scrollHeight-window.innerHeight;let p=height>0?window.scrollY/height:0;document.getElementById('reading-progress').style.transform=`scaleX(${Math.min(1,Math.max(0,p))})`}
document.addEventListener('click',event=>{const link=event.target.closest('a[data-route]');if(!link||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||busy)return;event.preventDefault();const url=new URL(link.href,location.href);if(url.pathname===location.pathname&&url.search===location.search){window.scrollTo({top:0,behavior:reduceMotion?'auto':'smooth'});closeMenu();return;}history.pushState(null,'',url.pathname+url.search);go();});
menuBtn.addEventListener('click',()=>{
  const isOpen=menuBtn.getAttribute('aria-expanded')==='true';
  if(isOpen){closeMenu();return;}
  updateMobileMenuPosition();
  mobileMenu.hidden=false;
  mobileMenu.scrollTop=0;
  menuBtn.setAttribute('aria-expanded','true');
  menuBtn.setAttribute('aria-label','Close navigation');
  document.body.classList.add('menu-open');
});
document.addEventListener('click',ev=>{const inPage=ev.target.closest('a[href^="#"]:not([href^="#/"])');if(inPage){const target=document.getElementById(inPage.getAttribute('href').slice(1));if(target){ev.preventDefault();target.scrollIntoView({behavior:reduceMotion?'auto':'smooth',block:'start'});document.querySelectorAll('.expertise-index a').forEach(a=>a.classList.toggle('is-active',a===inPage));return;}}const topic=ev.target.closest('[data-topic]');if(topic)selectTopic(topic.dataset.topic,false);const stage=ev.target.closest('[data-stage]');if(stage)selectStage(+stage.dataset.stage);const next=ev.target.closest('[data-stage-next], [data-stage-prev]');if(next)selectStage(+(next.dataset.stageNext ?? next.dataset.stagePrev)); const anatomy=ev.target.closest('[data-anatomy]');if(anatomy)selectAnatomy(+anatomy.dataset.anatomy); const scenario=ev.target.closest('[data-scenario]');if(scenario)selectScenario(scenario.dataset.scenario);const guide=ev.target.closest('[data-guide]');if(guide){history.replaceState(null,'',`insights.html?guide=${guide.dataset.guide}`);showGuide(guide.dataset.guide,true)}if(ev.target.closest('[data-back-guides]'))backToGuides();if(ev.target.closest('[data-close-dialog]'))document.getElementById('enquiry-dialog').close();if(ev.target.closest('[data-privacy]')){ev.preventDefault();document.getElementById('privacy-dialog').showModal()}if(ev.target.closest('[data-close-privacy]'))document.getElementById('privacy-dialog').close();});
document.getElementById('enquiry-dialog').addEventListener('click',ev=>{if(ev.target.id==='enquiry-dialog')ev.currentTarget.close()});document.getElementById('privacy-dialog').addEventListener('click',ev=>{if(ev.target.id==='privacy-dialog')ev.currentTarget.close()});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeMenu()});window.addEventListener('resize',()=>{if(window.innerWidth>860)closeMenu();else if(!mobileMenu.hidden)updateMobileMenuPosition()});window.addEventListener('scroll',updateProgress,{passive:true});window.addEventListener('popstate',go);
document.getElementById('year').textContent=new Date().getFullYear();
const legacyRoute=location.hash.match(/^#\/([a-z]+)(\?.*)?$/);if(legacyRoute && pages.includes(legacyRoute[1]))history.replaceState(null,'',routeFile(legacyRoute[1])+(legacyRoute[2]||''));
let initial=parseRoute();mount(initial.page,initial.query);
if(location.hash && !location.hash.startsWith('#/'))setTimeout(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView(),150);
